-- v3 (D-13): Adobe ARP FF K8 (K3) per-key base cells, SAMPLED BY WINDOW exactly as v2 11_k3_adobe_key_base_sampled.sql (14 whole 40-min buckets,
-- 04:00 and 16:00 UTC, 11-17 Nov), with PERCENTILE_CONT(0.999) added in the same scan. Output: d|grp|clean sig-windows|p99|p99.9|wins (+ CUR line).
-- Caveat: p99.9 on 14 of 252 windows rests on few signature-windows per cell; see caveats.md.
WITH s0 AS (SELECT session_ts ts, di_dictionary_num_matched_at_session_created d, di_matched_signature_at_session_created ms, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, IFF(latest_risk_band='High',1,0) hi, di_short_term_count_at_session_created stc, di_short_term_threshold_ratio_at_session_created str, di_long_term_count_at_session_created ltc, di_long_term_threshold_ratio_at_session_created ltr FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='BBCC314C-4937-4CCD-B0A3-FDF0F0F7603C' AND ((session_last_timestamp>='2026-11-11 04:00' AND session_last_timestamp<'2026-11-11 06:40') OR (session_last_timestamp>='2026-11-11 16:00' AND session_last_timestamp<'2026-11-11 18:40') OR (session_last_timestamp>='2026-11-12 04:00' AND session_last_timestamp<'2026-11-12 06:40') OR (session_last_timestamp>='2026-11-12 16:00' AND session_last_timestamp<'2026-11-12 18:40') OR (session_last_timestamp>='2026-11-13 04:00' AND session_last_timestamp<'2026-11-13 06:40') OR (session_last_timestamp>='2026-11-13 16:00' AND session_last_timestamp<'2026-11-13 18:40') OR (session_last_timestamp>='2026-11-14 04:00' AND session_last_timestamp<'2026-11-14 06:40') OR (session_last_timestamp>='2026-11-14 16:00' AND session_last_timestamp<'2026-11-14 18:40') OR (session_last_timestamp>='2026-11-15 04:00' AND session_last_timestamp<'2026-11-15 06:40') OR (session_last_timestamp>='2026-11-15 16:00' AND session_last_timestamp<'2026-11-15 18:40') OR (session_last_timestamp>='2026-11-16 04:00' AND session_last_timestamp<'2026-11-16 06:40') OR (session_last_timestamp>='2026-11-16 16:00' AND session_last_timestamp<'2026-11-16 18:40') OR (session_last_timestamp>='2026-11-17 04:00' AND session_last_timestamp<'2026-11-17 06:40') OR (session_last_timestamp>='2026-11-17 16:00' AND session_last_timestamp<'2026-11-17 18:40')) AND ((session_ts>='2026-11-11 04:00' AND session_ts<'2026-11-11 04:40') OR (session_ts>='2026-11-11 16:00' AND session_ts<'2026-11-11 16:40') OR (session_ts>='2026-11-12 04:00' AND session_ts<'2026-11-12 04:40') OR (session_ts>='2026-11-12 16:00' AND session_ts<'2026-11-12 16:40') OR (session_ts>='2026-11-13 04:00' AND session_ts<'2026-11-13 04:40') OR (session_ts>='2026-11-13 16:00' AND session_ts<'2026-11-13 16:40') OR (session_ts>='2026-11-14 04:00' AND session_ts<'2026-11-14 04:40') OR (session_ts>='2026-11-14 16:00' AND session_ts<'2026-11-14 16:40') OR (session_ts>='2026-11-15 04:00' AND session_ts<'2026-11-15 04:40') OR (session_ts>='2026-11-15 16:00' AND session_ts<'2026-11-15 16:40') OR (session_ts>='2026-11-16 04:00' AND session_ts<'2026-11-16 04:40') OR (session_ts>='2026-11-16 16:00' AND session_ts<'2026-11-16 16:40') OR (session_ts>='2026-11-17 04:00' AND session_ts<'2026-11-17 04:40') OR (session_ts>='2026-11-17 16:00' AND session_ts<'2026-11-17 16:40'))), s1 AS (SELECT s0.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp FROM s0), wg AS (SELECT d,grp,ms,TIME_SLICE(ts,40,'MINUTE') t,COUNT(*) n,SUM(hi) h FROM s1 WHERE x IS NULL AND ms IS NOT NULL GROUP BY 1,2,3,4), wp AS (SELECT d,'ALL' grp,ms,TIME_SLICE(ts,40,'MINUTE') t,COUNT(*) n,SUM(hi) h FROM s1 WHERE x IS NULL AND ms IS NOT NULL GROUP BY 1,2,3,4), w AS (SELECT * FROM wg UNION ALL SELECT * FROM wp) SELECT d||'|'||grp||'|'||COUNT_IF(h/n<0.2)||'|'||COALESCE(ROUND(PERCENTILE_CONT(0.99) WITHIN GROUP (ORDER BY IFF(h/n<0.2,n,NULL)),1)::STRING,'-')||'|'||COALESCE(ROUND(PERCENTILE_CONT(0.999) WITHIN GROUP (ORDER BY IFF(h/n<0.2,n,NULL)),1)::STRING,'-')||'|wins='||COUNT(DISTINCT t) r FROM w GROUP BY d,grp UNION ALL SELECT 'CUR|'||ROUND(MEDIAN(stc/NULLIF(str,0)),1)||'|'||ROUND(MEDIAN(ltc/NULLIF(ltr,0)),1)||'|n='||COUNT(*)||'|hi='||ROUND(AVG(hi),4) FROM s1 ORDER BY 1;
